-- Searing Gorge: creature abilities
-- Most of the zone's creatures (the Dark Iron of Thorium Point and the Cauldron, the fire elementals, golems, spiders and worgs) had no AI or ran classic rows. Port their abilities from the
-- Cataclysm data, and from the classic data where Cataclysm has none, keeping the quest scripts already in place; gossip and quest
-- reward scripts of the references are left out. The creatures no reference scripts cast their sniffed spells (creature_template
-- spell1-8).

SET @ENTRIES := '5833,5839,5840,5846,5855,5856,5857,8277,8278,8279,8280,8281,8282,8283,8391,8400,8566,9318,14621,14622,14636,26214,47271,47275,47276,47311,47434,47460,47462,47463,47470';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
